def max_sliding_window(nums, k):
    from collections import deque
    dq = deque()
    result = []
    for i, num in enumerate(nums):
        while dq and dq[-1] < num:
            dq.pop()
        dq.append(num)
        if i >= k and dq[0] == nums[i - k]:
            dq.popleft()
        if i >= k - 1:
            result.append(dq[0])
    return result
```

