class RateLimiter:
    def __init__(self, limit: int, window: int):
        self.limit = limit
        self.window = window
        self.events = {}  # key -> list of timestamps

    def allow(self, timestamp: int, key: str) -> bool:
        if key not in self.events:
            self.events[key] = []

        # Remove events outside the sliding window [timestamp - window + 1, timestamp]
        # The window is of size `window` ending at `timestamp`, so it includes timestamps in [timestamp - window + 1, timestamp]
        events = self.events[key]
        # Since timestamps are nondecreasing, we can remove from the front
        cutoff = timestamp - self.window + 1
        # Remove all events before cutoff
        while events and events[0] < cutoff:
            events.pop(0)

        if len(events) < self.limit:
            events.append(timestamp)
            return True
        else:
            return False
```

